INSERT INTO products (slug, name, category_id, short_desc, description, features, tech_stack, version, price, original_price, demo_video_url, demo_url, download_url, doc_url, file_size, product_type, is_featured, is_hot, is_new, sold_count, view_count, rating, rating_count) VALUES

('source-code-tool-tao-video-ai-veo3', 'Source Code Tool Tạo Video AI Veo 3 (Full Bản Quyền)', 1,
 'Full source code website tạo video AI tích hợp Veo 3 / Kling / Runway, có hệ thống thanh toán, quản lý user, credit.',
 '<h3>Giới thiệu</h3><p>Đây là <b>full source code</b> một nền tảng tạo video AI hoàn chỉnh, sẵn sàng thương mại hoá. Bạn nhận toàn bộ mã nguồn frontend + backend, không giới hạn số lần cài đặt, không giới hạn domain.</p><h3>Bạn nhận được gì?</h3><ul><li>Source code đầy đủ (frontend Next.js + backend Node.js)</li><li>Database schema + file migration</li><li>Tài liệu cài đặt chi tiết từng bước có ảnh minh hoạ</li><li>Video hướng dẫn deploy lên VPS / Vercel</li><li>Hỗ trợ kỹ thuật 6 tháng qua Zalo</li></ul><h3>Các bước triển khai</h3><p><b>Bước 1:</b> Tải source code từ link trong mục "Sản phẩm của tôi".<br><b>Bước 2:</b> Cài Node.js 20+, chạy <code>npm install</code>.<br><b>Bước 3:</b> Sao chép <code>.env.example</code> thành <code>.env</code>, điền API key Veo 3 / Kling / Runway.<br><b>Bước 4:</b> Chạy migration database.<br><b>Bước 5:</b> Chạy <code>npm run build && npm start</code>.<br><b>Bước 6:</b> Trỏ domain, bật SSL và bắt đầu bán credit cho khách.</p><h3>Phù hợp với ai?</h3><p>Người muốn kinh doanh dịch vụ tạo video AI, agency marketing, dev muốn học kiến trúc SaaS thực chiến.</p>',
 '["Tích hợp sẵn Veo 3, Kling, Runway, Luma","Hệ thống credit & nạp tiền tự động","Thanh toán VietQR + Momo webhook","Quản trị viên full quyền","Đa ngôn ngữ Việt/Anh","Responsive mọi thiết bị","Không giới hạn domain","Tặng kèm hosting guide"]',
 '["Next.js 14","Node.js","PostgreSQL","TailwindCSS","Redis","Docker"]',
 'v3.2', 2990000, 5990000, 'https://www.youtube.com/embed/aircAruvnKk', 'https://demo.srctool.ai/veo3', 'https://drive.google.com/drive/folders/DEMO-VEO3-SOURCE', 'https://docs.srctool.ai/veo3', '248 MB', 'source', 1, 1, 0, 342, 12840, 4.9, 128),

('source-code-app-tao-video-ban-hang-affiliate', 'Source Code App Tạo Video Bán Hàng Affiliate', 1,
 'App web tạo video review sản phẩm affiliate tự động: nhập link sản phẩm → ra video hoàn chỉnh có voice.',
 '<h3>Giới thiệu</h3><p>Source code app cho phép người dùng dán link sản phẩm Shopee/TikTok Shop, hệ thống tự crawl ảnh, viết kịch bản AI, tạo giọng đọc và render video dọc 9:16 sẵn sàng đăng TikTok.</p><h3>Luồng hoạt động</h3><p><b>Bước 1:</b> Người dùng dán link sản phẩm.<br><b>Bước 2:</b> Hệ thống crawl tiêu đề, giá, ảnh.<br><b>Bước 3:</b> GPT viết kịch bản review 30-45 giây.<br><b>Bước 4:</b> TTS tạo giọng đọc tiếng Việt tự nhiên.<br><b>Bước 5:</b> FFmpeg ghép ảnh + voice + nhạc nền + phụ đề.<br><b>Bước 6:</b> Xuất video MP4 tải về hoặc đăng thẳng lên kênh.</p>',
 '["Crawl tự động Shopee/Lazada/TikTok Shop","Viết kịch bản bằng GPT-4o","Giọng đọc tiếng Việt tự nhiên","Tự động thêm phụ đề động","Render hàng loạt (batch)","Kho nhạc nền bản quyền free"]',
 '["React","Express","FFmpeg","MongoDB","OpenAI API"]',
 'v2.5', 1990000, 3990000, 'https://www.youtube.com/embed/aircAruvnKk', '', 'https://drive.google.com/drive/folders/DEMO-AFF-SOURCE', 'https://docs.srctool.ai/affiliate', '180 MB', 'source', 1, 1, 0, 268, 9210, 4.8, 96),

('source-code-web-ban-tai-khoan-ai', 'Source Code Website Bán Tài Khoản / Key AI', 1,
 'Website bán tài khoản ChatGPT, Veo, Canva... giao key tự động 24/7, tích hợp cổng thanh toán.',
 '<h3>Giới thiệu</h3><p>Source code website bán tài khoản số, giao hàng tự động ngay sau khi khách chuyển khoản. Tích hợp bank webhook kiểm tra biến động số dư.</p><h3>Điểm mạnh</h3><p>Kho key tự động, hết hàng tự ẩn, cảnh báo tồn kho, thống kê doanh thu theo ngày/tháng, chống chia sẻ key.</p>',
 '["Giao key tự động sau thanh toán","Webhook biến động số dư ngân hàng","Kho key nhập hàng loạt CSV","Bảo hành key tự động","Dashboard doanh thu realtime"]',
 '["Laravel 11","MySQL","Vue 3","Bootstrap 5"]',
 'v4.0', 1490000, 2990000, '', '', 'https://drive.google.com/drive/folders/DEMO-KEY-SOURCE', '', '96 MB', 'source', 1, 0, 1, 154, 6120, 4.7, 61),

('source-code-tool-render-video-hang-loat', 'Source Code Tool Render Video Hàng Loạt (Bulk Render)', 1,
 'Tool desktop render 100+ video/ngày từ file Excel kịch bản, tự động ghép ảnh - voice - sub.',
 '<h3>Giới thiệu</h3><p>Tool desktop (Electron) đọc file Excel danh sách kịch bản và render hàng loạt video. Phù hợp team làm content số lượng lớn, nuôi nhiều kênh TikTok/YouTube.</p><h3>Cách dùng</h3><p><b>Bước 1:</b> Chuẩn bị file Excel theo mẫu (tiêu đề, kịch bản, thư mục ảnh).<br><b>Bước 2:</b> Chọn preset khung hình 9:16 hoặc 16:9.<br><b>Bước 3:</b> Bấm Render All và đi ngủ.</p>',
 '["Render đa luồng tận dụng full CPU","Đọc kịch bản từ Excel/Google Sheet","Tự động thêm intro/outro","Đổi seed random tránh trùng nội dung","Hàng đợi thông minh, tiếp tục khi mất điện"]',
 '["Electron","Node.js","FFmpeg","SQLite"]',
 'v1.8', 1290000, 2490000, '', '', 'https://drive.google.com/drive/folders/DEMO-BULK-SOURCE', '', '312 MB', 'source', 0, 1, 0, 187, 5400, 4.6, 52),

('chatbot-kich-ban-thoi-trang-nu', 'Chatbot Viết Kịch Bản Video Thời Trang Nữ', 2,
 'Chatbot tạo sẵn 6 prompt ảnh + 6 prompt video cho ngành thời trang nữ, dùng với Veo 3 / Flow.',
 '<h3>Giới thiệu</h3><p>Chatbot hỗ trợ tạo nội dung video bằng AI dành cho shop thời trang nữ, KOC review quần áo, người bán hàng online. Phù hợp cho người không biết quay dựng, không biết viết prompt.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Mở link chatbot trong mục "Sản phẩm của tôi".<br><b>Bước 2:</b> Bấm câu lệnh Start.<br><b>Bước 3:</b> Chọn chủ đề (dạo phố, thử đồ, catwalk, unbox...).<br><b>Bước 4:</b> Chatbot trả về 6 prompt tạo ảnh và 6 prompt tạo video.<br><b>Bước 5:</b> Copy prompt ảnh số 1 dán vào Flow/Veo 3, tải ảnh KOC tham chiếu lên.<br><b>Bước 6:</b> Lần lượt tạo đủ 6 ảnh, dùng ảnh trước làm tham chiếu cho ảnh sau để đồng nhất nhân vật.<br><b>Bước 7:</b> Copy prompt video, chọn model Omni, thời lượng 8 giây và render.<br><b>Bước 8:</b> Tải video về, ghép trong CapCut, thêm nhạc và CTA.</p>',
 '["6 prompt ảnh + 6 prompt video mỗi lần chạy","Giữ nhân vật đồng nhất giữa các cảnh","Tối ưu cho khung dọc 9:16 TikTok","Có sẵn 12 chủ đề ngành thời trang","Cập nhật prompt miễn phí trọn đời"]',
 '["ChatGPT","Gemini","Veo 3","Flow"]',
 'v1.0', 199000, 299000, '', '', 'https://chatgpt.com/g/demo-thoi-trang-nu', '', '—', 'chatbot', 1, 1, 0, 892, 21400, 4.9, 314),

('chatbot-kich-ban-my-pham-koc', 'Chatbot Viết Kịch Bản KOC Review Mỹ Phẩm', 2,
 'Tạo kịch bản + prompt video KOC review mỹ phẩm, skincare, làm đẹp chuẩn viral TikTok.',
 '<h3>Giới thiệu</h3><p>Chatbot chuyên ngành mỹ phẩm: serum, kem chống nắng, son, skincare routine. Tự sinh kịch bản theo công thức Hook - Pain - Solution - CTA.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Mở chatbot, bấm Start.<br><b>Bước 2:</b> Nhập tên sản phẩm và công dụng chính.<br><b>Bước 3:</b> Chọn tone: chuyên gia, bạn thân, hài hước.<br><b>Bước 4:</b> Nhận 6 cảnh có prompt ảnh + prompt video.<br><b>Bước 5:</b> Render trên Veo 3 và ghép lại bằng CapCut.</p>',
 '["Công thức Hook 3 giây giữ chân người xem","Kịch bản chuẩn ngành beauty","Prompt tả kỹ ánh sáng studio đẹp da","Gợi ý CTA chốt đơn affiliate"]',
 '["ChatGPT","Veo 3"]',
 'v1.2', 199000, 299000, '', '', 'https://chatgpt.com/g/demo-my-pham', '', '—', 'chatbot', 1, 1, 1, 654, 15800, 4.8, 221),

('chatbot-kich-ban-do-gia-dung', 'Chatbot Kịch Bản Video Đồ Gia Dụng Nhân Hoá', 2,
 'Chatbot tạo video đồ gia dụng "biết nói" - phong cách nhân hoá siêu viral, bán hàng affiliate.',
 '<h3>Giới thiệu</h3><p>Biến nồi chiên, máy hút bụi, máy xay thành nhân vật biết nói chuyện hài hước. Dạng video đang cực viral trên TikTok Shop.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Mở chatbot và bấm Start.<br><b>Bước 2:</b> Nhập tên món đồ gia dụng.<br><b>Bước 3:</b> Chatbot dựng 6 cảnh hội thoại nhân hoá.<br><b>Bước 4:</b> Copy prompt sang Veo 3 chế độ Omni có audio.<br><b>Bước 5:</b> Ghép video và thêm link giỏ hàng.</p>',
 '["Nhân hoá đồ vật cực hài","Có sẵn lời thoại tiếng Việt","Prompt audio đồng bộ khẩu hình","Phù hợp affiliate TikTok Shop"]',
 '["ChatGPT","Veo 3 Omni"]',
 'v1.0', 179000, 299000, '', '', 'https://chatgpt.com/g/demo-gia-dung', '', '—', 'chatbot', 0, 1, 0, 421, 9800, 4.7, 143),

('chatbot-kich-ban-nong-nghiep', 'Chatbot Kịch Bản Video Nông Nghiệp - Hạt Giống', 2,
 'Chatbot viết kịch bản video bán hạt giống, phân bón, máy nông nghiệp theo phong cách thực tế.',
 '<h3>Giới thiệu</h3><p>Dành cho đại lý vật tư nông nghiệp, người bán hạt giống, phân bón online. Kịch bản mộc mạc, dễ tin, chuyển đổi cao với tệp khách nông thôn.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Bấm Start.<br><b>Bước 2:</b> Chọn nhóm sản phẩm: hạt giống, phân bón, máy móc.<br><b>Bước 3:</b> Nhận 6 prompt ảnh + 6 prompt video theo mùa vụ.<br><b>Bước 4:</b> Render và đăng lên Facebook/TikTok.</p>',
 '["Kịch bản đúng ngôn ngữ nhà nông","Cảnh quay đồng ruộng chân thực","Có biến thể theo mùa vụ","Gợi ý CTA đặt hàng qua Zalo"]',
 '["ChatGPT","Veo 3"]',
 'v1.0', 169000, 269000, '', '', 'https://chatgpt.com/g/demo-nong-nghiep', '', '—', 'chatbot', 0, 0, 1, 213, 5600, 4.6, 78),

('chatbot-kich-ban-dong-y-massage', 'Chatbot Kịch Bản Phòng Khám Đông Y, Massage Bấm Huyệt', 2,
 'Tạo video quảng bá phòng khám đông y, spa trị liệu, massage cổ vai gáy bằng AI.',
 '<h3>Giới thiệu</h3><p>Chatbot hỗ trợ tạo nội dung video bằng AI dành cho phòng khám đông y, spa trị liệu, massage bấm huyệt, chăm sóc sức khoẻ. Phù hợp cho người muốn làm video quảng bá dịch vụ nhưng không biết quay dựng.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Mở chatbot từ mục "Sản phẩm của tôi".<br><b>Bước 2:</b> Bấm Start.<br><b>Bước 3:</b> Chọn chủ đề: massage cổ vai gáy, bấm huyệt thư giãn, đau lưng, tê bì chân tay...<br><b>Bước 4:</b> Nhận 6 prompt ảnh và 6 prompt video.<br><b>Bước 5:</b> Tạo ảnh lần lượt trên Flow/Veo 3, dùng ảnh trước làm tham chiếu.<br><b>Bước 6:</b> Tạo video 8 giây cho từng cảnh.<br><b>Bước 7:</b> Ghép trong CapCut, thêm logo, số điện thoại, địa chỉ phòng khám.</p><p><i>Lưu ý: Nội dung nên dùng cho mục đích truyền thông, không thay thế tư vấn y tế chuyên môn.</i></p>',
 '["6 cảnh nội dung mỗi chủ đề","Bối cảnh phòng khám chuyên nghiệp","Giữ nhân vật kỹ thuật viên đồng nhất","Phù hợp TikTok, Reels, Shorts"]',
 '["ChatGPT","Veo 3","Flow"]',
 'v1.0', 199000, 299000, '', '', 'https://chatgpt.com/g/demo-dong-y', '', '—', 'chatbot', 1, 0, 1, 176, 4900, 4.8, 64),

('chatbot-video-stickman-dao-ly', 'Chatbot Tạo Video Hoạt Hình Stickman Đạo Lý', 2,
 'Chatbot dựng video stickman kể chuyện đạo lý, kinh tế, chính trị - dạng viral triệu view.',
 '<h3>Giới thiệu</h3><p>Chatbot viết kịch bản và prompt tạo video hoạt hình stickman đơn giản nhưng cực dễ viral. Dùng để build kênh triệu view hoặc bán sách affiliate.</p><h3>Các bước sử dụng</h3><p><b>Bước 1:</b> Bấm Start, chọn chủ đề đạo lý / kinh tế / kỹ năng.<br><b>Bước 2:</b> Chatbot trả kịch bản 60 giây chia 8 cảnh.<br><b>Bước 3:</b> Copy prompt hình que sang Veo 3.<br><b>Bước 4:</b> Ghép và thêm giọng đọc TTS.</p>',
 '["Kịch bản 8 cảnh chuẩn viral","Style hình que nhất quán","Có sẵn 30 chủ đề đạo lý","Gợi ý nhạc nền phù hợp"]',
 '["ChatGPT","Veo 3"]',
 'v1.1', 149000, 249000, '', '', 'https://chatgpt.com/g/demo-stickman', '', '—', 'chatbot', 0, 1, 0, 538, 13200, 4.7, 187),

('bo-prompt-veo3-500-mau', 'Bộ 500 Prompt Veo 3 Chuẩn Điện Ảnh', 3,
 '500 prompt mẫu Veo 3 đã test kỹ, chia 20 chủ đề: sản phẩm, thời trang, ẩm thực, du lịch, POV...',
 '<h3>Giới thiệu</h3><p>Bộ prompt được tuyển chọn và test thực tế trên Veo 3, đảm bảo ra video đẹp ngay lần đầu. Mỗi prompt có mô tả camera, ánh sáng, chuyển động, âm thanh.</p><h3>Cách dùng</h3><p><b>Bước 1:</b> Mở Google Sheet trong mục "Sản phẩm của tôi".<br><b>Bước 2:</b> Tìm chủ đề mong muốn.<br><b>Bước 3:</b> Copy prompt, thay biến [SẢN PHẨM] bằng sản phẩm của bạn.<br><b>Bước 4:</b> Dán vào Veo 3 và render.</p>',
 '["500 prompt đã test thực tế","20 chủ đề ngành hàng","Có ảnh kết quả tham khảo","Định dạng Google Sheet dễ tra cứu","Update thêm prompt mỗi tháng"]',
 '["Veo 3","Flow","Kling"]',
 'v2.0', 299000, 599000, '', '', 'https://docs.google.com/spreadsheets/d/DEMO-500-PROMPT', '', '—', 'prompt', 1, 1, 0, 1240, 32100, 4.9, 428),

('prompt-tao-anh-nhan-vat-dong-nhat', 'Bộ Prompt Tạo Nhân Vật AI Đồng Nhất 4K', 3,
 'Kỹ thuật + bộ prompt giữ khuôn mặt nhân vật AI không đổi qua hàng chục cảnh quay.',
 '<h3>Giới thiệu</h3><p>Vấn đề lớn nhất khi làm video AI là nhân vật bị đổi mặt giữa các cảnh. Bộ tài liệu này giải quyết triệt để bằng kỹ thuật ảnh tham chiếu + prompt khoá đặc điểm.</p><h3>Nội dung</h3><p>Gồm 80 prompt tả nhân vật chi tiết, quy trình 7 bước khoá gương mặt, và 15 ảnh KOC mẫu dùng làm reference.</p>',
 '["80 prompt tả nhân vật chi tiết","Quy trình 7 bước khoá gương mặt","15 ảnh KOC mẫu bản quyền free","Áp dụng cho Veo 3, Flow, Midjourney"]',
 '["Veo 3","Flow","Midjourney"]',
